struct Bus {
    subs: Mutex<Vec<Arc<dyn Fn(&OrderPlaced) + Send + Sync>>>,
}

impl Bus {
    pub fn subscribe(&self, h: Arc<dyn Fn(&OrderPlaced) + Send + Sync>) {
        self.subs.lock().unwrap().push(h);
    }
    pub fn publish(&self, event: &OrderPlaced) {
        let snapshot: Vec<_> = self.subs.lock().unwrap().clone();  // drop the lock first
        for handler in &snapshot { handler(event); }
    }
}
